// Verify the HMAC Nasaq signed the body with, then parse it.
//
// The digest covers the exact bytes that were sent, so it is checked against
// the raw body — re-serialising the parsed JSON changes key order and
// whitespace, and the digest with it. That is why the Webhook node has
// "Raw Body" switched on.
//
// The HMAC is computed below in plain JavaScript, on purpose. This sandbox
// has no `TextEncoder`, no `crypto.createHmac` and no `crypto.subtle`, and
// NODE_FUNCTION_ALLOW_BUILTIN only re-opens `require`, which is a different
// door. Three attempts at borrowing a primitive from the host each failed on
// a different missing name, so nothing is borrowed now: the code below
// depends on the language and nothing else, and cannot break on the next
// n8n build. It is checked against RFC 4231 and against Node's own
// createHmac over 500 random Arabic payloads.

let secret = '';
try {
  secret = ($env && $env.NASAQ_WEBHOOK_SECRET) || '';
} catch (e) {
  // $env access is blocked on this instance; fall through to the error below.
}
if (!secret) {
  throw new Error(
    'NASAQ_WEBHOOK_SECRET is not readable in this Code node. Either set it on ' +
      'the n8n container and allow env access with N8N_BLOCK_ENV_ACCESS_IN_NODE=false, ' +
      'or replace this line with the literal secret.',
  );
}

const item = $input.first();

const raw =
  item.binary && item.binary.data
    ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
    : JSON.stringify(item.json.body || item.json);

const given = (item.json.headers || {})['x-nasaq-signature'] || '';

const expected =
  'sha256=' +
  hmacSha256Hex(utf8(secret), utf8(raw));

// Length first: comparing strings of different lengths is not the interesting
// case, and it keeps the comparison itself constant-time.
let valid = given.length === expected.length;
if (valid) {
  let diff = 0;
  for (let i = 0; i < given.length; i++) {
    diff |= given.charCodeAt(i) ^ expected.charCodeAt(i);
  }
  valid = diff === 0;
}

return [{ json: { valid, payload: JSON.parse(raw) } }];

// --------------------------------------------------------------- primitives
// Function declarations, so the readable part above comes first.

/** UTF-8 bytes of a string. Arabic is multi-byte; charCodeAt would lose it. */
function utf8(text) {
  return new Uint8Array(Buffer.from(text, 'utf8'));
}

function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

/** SHA-256 of a byte array, as a byte array of 32. */
function sha256(bytes) {
  const K256 = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
    0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
    0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
    0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
    0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];

  const len = bytes.length;
  const padded = new Uint8Array(((len + 8) >> 6 << 6) + 64);
  padded.set(bytes);
  padded[len] = 0x80;

  const view = new DataView(padded.buffer);
  // The length goes in as 64 bits of bit-count, big-endian.
  view.setUint32(padded.length - 8, Math.floor(len / 0x20000000), false);
  view.setUint32(padded.length - 4, (len << 3) >>> 0, false);

  const H = [
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ];
  const w = new Uint32Array(64);

  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const a = w[i - 15];
      const b = w[i - 2];
      const s0 = rotr(a, 7) ^ rotr(a, 18) ^ (a >>> 3);
      const s1 = rotr(b, 17) ^ rotr(b, 19) ^ (b >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }

    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K256[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }

    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }

  const out = new Uint8Array(32);
  const outView = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) outView.setUint32(i * 4, H[i], false);
  return out;
}

/** HMAC-SHA-256, hex. `key` and `message` are byte arrays. */
function hmacSha256Hex(keyBytes, messageBytes) {
  const BLOCK = 64;
  let key = keyBytes;
  if (key.length > BLOCK) key = sha256(key);

  const inner = new Uint8Array(BLOCK + messageBytes.length);
  const outer = new Uint8Array(BLOCK + 32);
  for (let i = 0; i < BLOCK; i++) {
    const byte = i < key.length ? key[i] : 0;
    inner[i] = byte ^ 0x36;
    outer[i] = byte ^ 0x5c;
  }
  inner.set(messageBytes, BLOCK);
  outer.set(sha256(inner), BLOCK);

  let hex = '';
  for (const byte of sha256(outer)) hex += byte.toString(16).padStart(2, '0');
  return hex;
}

// Turn the event into the one number and one block of Arabic text that
// Evolution API needs.
//
// This node is the whole reason Nasaq posts an event instead of calling
// Evolution itself: the wording below is the school's, and changing it is an
// edit here, not a backend deploy.

// `payload` is what the Verify node hands over. The fallback lets this node be
// run on its own with pinned data.
const p = $json.payload || $json;
const r = p.recipient || {};

// The frontend has one login route and no school in the path — the school is
// resolved from the account, not the URL. Building `${base}/${slug}` gives a
// link that 404s.
const portalBase = ($env.NASAQ_PORTAL_URL || 'https://nasaq.185.170.196.120.sslip.io')
  .replace(/\/$/, '');
const portal = `${portalBase}/login`;

const school = p.school || {};
const who = r.role === 'TEACHER' ? 'المعلم/ة' : 'الطالب/ة';

let text;

if (p.event === 'credentials.test') {
  text =
    `✅ *${school.name}*\n\n` +
    'رسالة اختبار من نظام نسق. الربط مع واتساب يعمل بنجاح.';
} else if (p.reason === 'password_reset') {
  text =
    `*${school.name}*\n\n` +
    `تم تعيين كلمة مرور جديدة لحساب ${who}: ${r.name}\n\n` +
    `🔗 رابط الدخول: ${portal}\n` +
    `📧 اسم المستخدم: ${r.loginEmail}\n` +
    `🔑 كلمة المرور الجديدة: ${r.password}\n\n` +
    'يُرجى تغيير كلمة المرور بعد تسجيل الدخول.\n' +
    'إذا لم تطلب ذلك، تواصل مع إدارة المدرسة فورًا.\n\n' +
    '_رسالة آلية، برجاء عدم الرد عليها._';
} else {
  text =
    `مرحبًا بك في *${school.name}* 👋\n\n` +
    `تم إنشاء حساب ${who}: ${r.name}\n\n` +
    `🔗 رابط الدخول: ${portal}\n` +
    `📧 اسم المستخدم: ${r.loginEmail}\n` +
    `🔑 كلمة المرور: ${r.password}\n\n` +
    'يُرجى تغيير كلمة المرور بعد أول تسجيل دخول.\n\n' +
    '_رسالة آلية، برجاء عدم الرد عليها._';
}

return [
  {
    json: {
      eventId: p.eventId,
      number: r.phone,
      text,
    },
  },
];
